#!/usr/bin/env bash
set -euo pipefail
cd "${1:-$PWD}"

[[ -f analysis/functions/cdvd_rpc_0019be70.asm ]] || {
  echo "Run from SNESstation-Decomp repository root." >&2
  exit 2
}

mkdir -p matching/candidates matching/ee_abi_compat tools docs analysis/matching

python3 - <<'PY'
from pathlib import Path
Path("matching/ee_abi_compat/cdvd_legacy_compat.h").write_text('#ifndef SNESSTATION_CDVD_LEGACY_COMPAT_H\n#define SNESSTATION_CDVD_LEGACY_COMPAT_H\n\ntypedef unsigned char u8;\ntypedef unsigned int u32;\ntypedef unsigned int size_t;\n\n#ifndef NULL\n#define NULL ((void *)0)\n#endif\n\ntypedef void (*SifRpcEndFunc_t)(void *);\n\nstruct t_SifRpcServerData;\n\ntypedef struct t_SifRpcHeader\n{\n    void *pkt_addr;\n    u32 rpc_id;\n    int sema_id;\n    u32 mode;\n} SifRpcHeader_t;\n\n/*\n * Historical PS2 SIF RPC client layout.  On the EE ABI used here:\n *   sizeof(SifRpcHeader_t) == 0x10\n *   offsetof(server)       == 0x24\n *   sizeof(client)         == 0x28\n *\n * The SNES Station target independently confirms server at +0x24 in\n * CDVD_Init (lw ..., 0x24($s0)).\n */\ntypedef struct t_SifRpcClientData\n{\n    struct t_SifRpcHeader hdr;\n    u32 command;\n    void *buff, *cbuff;\n    SifRpcEndFunc_t end_function;\n    void *end_param;\n    struct t_SifRpcServerData *server;\n} SifRpcClientData_t;\n\nstruct TocEntry\n{\n    u32 fileLBA;\n    u32 fileSize;\n    u8 fileProperties;\n    u8 padding1[3];\n    char filename[128+1];\n    u8 padding2[3];\n} __attribute__((packed));\n\nenum CDVD_getMode {\n    CDVD_GET_FILES_ONLY = 1,\n    CDVD_GET_DIRS_ONLY = 2,\n    CDVD_GET_FILES_AND_DIRS = 3\n};\n\n#define CDVD_IRX        0xB001337\n#define CDVD_FINDFILE   0x01\n#define CDVD_GETDIR     0x02\n#define CDVD_STOP       0x04\n#define CDVD_TRAYREQ    0x05\n#define CDVD_DISKREADY  0x06\n#define CDVD_FLUSHCACHE 0x07\n#define CDVD_GETSIZE    0x08\n\nint SifBindRpc(SifRpcClientData_t *client, int rpc_number, int mode);\nint SifCallRpc(SifRpcClientData_t *client, int rpc_number, int mode,\n               void *send, int ssize, void *receive, int rsize,\n               SifRpcEndFunc_t end_function, void *end_param);\nvoid SifWriteBackDCache(void *ptr, int size);\n\nchar *strncpy(char *dest, const char *src, size_t n);\nvoid *memcpy(void *dest, const void *src, size_t n);\n\n#endif\n', encoding="utf-8")
Path("matching/candidates/cdvd_rpc.c").write_text('/*\n * Exact-source-shape candidate for the historical libcdvd EE client.\n *\n * Functions CDVD_Init through CDVD_FlushCache are preserved in the\n * SNESticle source tree.  CDVD_GetSize and CDVD_GETSIZE=0x08 survive in the\n * PGEN copy of the same libcdvd family.\n *\n * Keep names, declaration order and expression shapes historical here.\n */\n#include "cdvd_legacy_compat.h"\n\nint k_sceSifDmaStat(unsigned int id);\nstatic unsigned sbuff[0x1300] __attribute__((aligned (64)));\nstatic SifRpcClientData_t cd0;\n\nint cdvd_inited = 0;\n\nint CDVD_Init()\n{\n    int i;\n\n    while(1){\n        if (SifBindRpc( &cd0, CDVD_IRX, 0) < 0) return -1;\n        if (cd0.server != 0) break;\n        i = 0x10000;\n        while(i--);\n    }\n\n    cdvd_inited = 1;\n\n    return 0;\n}\n\nint CDVD_DiskReady(int mode)\n{\n    if(!cdvd_inited) return -1;\n\n    sbuff[0] = mode;\n\n    SifCallRpc(&cd0,CDVD_DISKREADY,0,(void*)(&sbuff[0]),4,(void*)(&sbuff[0]),4,0,0);\n\n    return sbuff[0];\n}\n\nint CDVD_FindFile(const char* fname, struct TocEntry* tocEntry)\n{\n    if(!cdvd_inited) return -1;\n\n    strncpy((char*)&sbuff,fname,1024);\n\n    SifCallRpc(&cd0,CDVD_FINDFILE,0,(void*)(&sbuff[0]),1024,(void*)(&sbuff[0]),sizeof(struct TocEntry)+1024,0,0);\n\n    memcpy(tocEntry, &sbuff[256], sizeof(struct TocEntry));\n\n    return sbuff[0];\n}\n\nvoid CDVD_Stop()\n{\n    if(!cdvd_inited) return;\n\n    SifCallRpc(&cd0,CDVD_STOP,0,(void*)(&sbuff[0]),0,(void*)(&sbuff[0]),0,0,0);\n\n    return;\n}\n\nint CDVD_TrayReq(int mode)\n{\n    if(!cdvd_inited) return -1;\n\n    SifCallRpc(&cd0,CDVD_TRAYREQ,0,(void*)(&sbuff[0]),4,(void*)(&sbuff[0]),4,0,0);\n\n    return sbuff[0];\n}\n\nint CDVD_getdir(const char* pathname, const char* extensions, enum CDVD_getMode getMode, struct TocEntry tocEntry[], unsigned int req_entries, char* new_pathname)\n{\n    unsigned int num_entries;\n\n    if(!cdvd_inited) return -1;\n\n    strncpy((char*)sbuff,pathname,1023);\n\n    if (extensions == NULL)\n    {\n        sbuff[1024/4] = 0;\n    }\n    else\n    {\n        strncpy((char*)&sbuff[1024/4],extensions,127);\n    }\n\n    sbuff[1152/4] = getMode;\n\n    sbuff[1156/4] = (int)tocEntry;\n\n    sbuff[1160/4] = req_entries;\n\n    SifWriteBackDCache(tocEntry, req_entries*sizeof(struct TocEntry));\n\n    SifCallRpc(&cd0,CDVD_GETDIR,0,(void*)(&sbuff[0]),1024+128+4+4+4,(void*)(&sbuff[0]),4+1024,0,0);\n\n    num_entries = sbuff[0];\n\n    if (new_pathname != NULL)\n        strncpy(new_pathname,(char*)&sbuff[1],1023);\n\n    return (num_entries);\n}\n\nvoid CDVD_FlushCache()\n{\n    if(!cdvd_inited) return;\n\n    SifCallRpc(&cd0,CDVD_FLUSHCACHE,0,(void*)(&sbuff[0]),0,(void*)(&sbuff[0]),0,0,0);\n\n    return;\n}\n\nunsigned int CDVD_GetSize()\n{\n    if(!cdvd_inited) return;\n\n    SifCallRpc(&cd0,CDVD_GETSIZE,0,(void*)(&sbuff[0]),0,(void*)(&sbuff[0]),4,0,0);\n\n    return sbuff[0];\n}\n', encoding="utf-8")
Path("analysis/matching/cdvd_rpc_listing.csv").write_text('address,end,name,object_symbol,source\n0x0019be70,0x0019bf00,CDVD_Init,CDVD_Init,matching/candidates/cdvd_rpc.c\n0x0019bf00,0x0019bf70,CDVD_DiskReady,CDVD_DiskReady,matching/candidates/cdvd_rpc.c\n0x0019bf70,0x0019c0d0,CDVD_FindFile,CDVD_FindFile,matching/candidates/cdvd_rpc.c\n0x0019c0d0,0x0019c128,CDVD_Stop,CDVD_Stop,matching/candidates/cdvd_rpc.c\n0x0019c128,0x0019c190,CDVD_TrayReq,CDVD_TrayReq,matching/candidates/cdvd_rpc.c\n0x0019c190,0x0019c2ac,CDVD_getdir,CDVD_getdir,matching/candidates/cdvd_rpc.c\n0x0019c2ac,0x0019c304,CDVD_FlushCache,CDVD_FlushCache,matching/candidates/cdvd_rpc.c\n0x0019c304,0x0019c364,CDVD_GetSize,CDVD_GetSize,matching/candidates/cdvd_rpc.c\n', encoding="utf-8")
Path("tools/score_cdvd_candidate.py").write_text('#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport importlib.util\nfrom pathlib import Path\n\n\ndef load_compare(root: Path):\n    path = root / "tools" / "compare_elf_functions.py"\n    spec = importlib.util.spec_from_file_location("compare_elf_functions_local", path)\n    if spec is None or spec.loader is None:\n        raise SystemExit("cannot load compare_elf_functions.py")\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--target", required=True, type=Path)\n    parser.add_argument("--base-address", required=True, type=lambda x: int(x, 0))\n    parser.add_argument("--object", required=True, type=Path)\n    parser.add_argument("--manifest", required=True, type=Path)\n    parser.add_argument("--label", default="")\n    parser.add_argument("--tsv", action="store_true")\n    args = parser.parse_args()\n\n    root = Path(__file__).resolve().parents[1]\n    cmpmod = load_compare(root)\n\n    target = args.target.read_bytes()\n    elf = cmpmod.ELFFile(args.object)\n    rows = list(csv.DictReader(args.manifest.open(encoding="utf-8", newline="")))\n\n    results = []\n    for row in rows:\n        address = int(row["address"], 0)\n        end = int(row["end"], 0)\n        result = cmpmod.compare_function(\n            target,\n            address - args.base_address,\n            end - address,\n            elf,\n            row["object_symbol"],\n        )\n        results.append((row, result))\n\n    matches = sum(r.matching for _, r in results)\n    same_size = sum(r.expected_size == r.candidate_size for _, r in results)\n    size_delta = sum(abs(r.expected_size - r.candidate_size) for _, r in results)\n    diff_bytes = sum(r.differing_bytes for _, r in results)\n\n    if args.tsv:\n        print(\n            f"{args.label}\\t{matches}\\t{same_size}\\t{size_delta}\\t{diff_bytes}"\n        )\n        return\n\n    print(\n        f"score: matches={matches}/{len(results)} "\n        f"same-size={same_size}/{len(results)} "\n        f"size-delta={size_delta} diff-bytes={diff_bytes}"\n    )\n    for row, r in results:\n        status = "MATCH" if r.matching else "MISS "\n        first = ", ".join(f"+0x{x:x}" for x in r.first_differences) or "-"\n        print(\n            f"  {status} {row[\'address\']} {row[\'name\']}: "\n            f"{r.expected_size}/{r.candidate_size}, "\n            f"diff-bytes={r.differing_bytes}, first={first}"\n        )\n\n\nif __name__ == "__main__":\n    main()\n', encoding="utf-8")
Path("tools/run-cdvd-frontier.sh").write_text('#!/usr/bin/env bash\nset -euo pipefail\n\nROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"\ncd "$ROOT"\n\nDEFAULT_EE_CC="$ROOT/build/toolchains/ee-gcc-3.2.2-stage1/prefix/bin/ee-gcc"\nEE_CC="${EE_CC:-$DEFAULT_EE_CC}"\n\nif [[ ! -x "$EE_CC" ]]; then\n    echo "Missing historical EE compiler: $EE_CC" >&2\n    exit 2\nfi\n\nBUILD="$ROOT/build/matching/cdvd_rpc"\nSOURCE="$ROOT/matching/candidates/cdvd_rpc.c"\nMANIFEST="$ROOT/analysis/matching/cdvd_rpc_listing.csv"\nRAW="$BUILD/listing.bin"\n\nmkdir -p "$BUILD"\nrm -f "$BUILD"/shape-*.o "$BUILD"/shape-*.compile.log\nrm -f "$BUILD"/shape-scores.tsv "$BUILD"/best-profile.txt\nrm -f "$BUILD"/best-objdump.txt "$RAW"\n\npython3 tools/objdump_listing_to_binary.py \\\n  --input analysis/functions/cdvd_rpc_0019be70.asm \\\n  --output "$RAW" \\\n  --base-address 0x0019be70 \\\n  --end-address 0x0019c364 >/dev/null\n\nCOMMON=(\n  -G0 -EL -pipe -Wall\n  -fshort-double -mlong64 -mhard-float -mno-abicalls\n  -march=r5900 -mtune=r5900\n  -DPS2_EE -D_EE -DLSB_FIRST -DALIGN_DWORD -DCODE_PLATFORM=3\n  -Imatching/ee_abi_compat\n)\n\ntry_profile() {\n    local name="$1"\n    shift\n    local obj="$BUILD/shape-${name}.o"\n    local log="$BUILD/shape-${name}.compile.log"\n\n    if ! "$EE_CC" "$@" "${COMMON[@]}" -c "$SOURCE" -o "$obj" >"$log" 2>&1; then\n        printf \'%s\\tFAIL\\t0\\t999999\\t999999\\n\' "$name" >>"$BUILD/shape-scores.tsv"\n        return 0\n    fi\n\n    python3 tools/score_cdvd_candidate.py \\\n      --target "$RAW" \\\n      --base-address 0x0019be70 \\\n      --object "$obj" \\\n      --manifest "$MANIFEST" \\\n      --label "$name" \\\n      --tsv >>"$BUILD/shape-scores.tsv"\n}\n\n# Faithful historical baselines.\ntry_profile o2-strict \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common\n\ntry_profile o2-default-alias \\\n  -O2 -fomit-frame-pointer -fno-common\n\ntry_profile o2-no-strict \\\n  -O2 -fomit-frame-pointer -fno-strict-aliasing -fno-common\n\n# Scheduler fingerprints.\ntry_profile o2-no-sched1 \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-schedule-insns\n\ntry_profile o2-no-sched2 \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-schedule-insns2\n\ntry_profile o2-no-sched12 \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-schedule-insns -fno-schedule-insns2\n\ntry_profile o2-no-delayed \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-delayed-branch\n\ntry_profile o2-no-sched1-no-delayed \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-schedule-insns -fno-delayed-branch\n\n# Individual O2 passes that can move prologues/branches/register lifetimes.\ntry_profile o2-no-gcse \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-gcse\n\ntry_profile o2-no-crossjump \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-crossjumping\n\ntry_profile o2-no-cse-follow \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-cse-follow-jumps\n\ntry_profile o2-no-expensive \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-expensive-optimizations\n\ntry_profile o2-no-peephole2 \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-peephole2\n\ntry_profile o2-no-reorder-blocks \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-reorder-blocks\n\ntry_profile o2-no-ifconv \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-if-conversion\n\ntry_profile o2-no-ifconv2 \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-if-conversion2\n\n# Optimization-level controls.\ntry_profile o1 \\\n  -O1 -fomit-frame-pointer -fstrict-aliasing -fno-common\n\ntry_profile o3 \\\n  -O3 -fomit-frame-pointer -fstrict-aliasing -fno-common\n\n# Surviving SNESticle Makefile profile, kept as a negative/positive control.\ntry_profile snesticle-freestanding \\\n  -O2 -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -ffreestanding -fno-builtin\n\nBEST="$(python3 - "$BUILD/shape-scores.tsv" <<\'PY\'\nimport sys\nfrom pathlib import Path\n\nrows = []\nfor line in Path(sys.argv[1]).read_text(encoding="utf-8").splitlines():\n    p = line.split("\\t")\n    if len(p) != 5 or p[1] == "FAIL":\n        continue\n    name = p[0]\n    matches = int(p[1])\n    same_size = int(p[2])\n    size_delta = int(p[3])\n    diff_bytes = int(p[4])\n    # Exact matches dominate; then actual relocation-normalized differing\n    # bytes; then shape/size proximity.\n    rows.append((matches, -diff_bytes, same_size, -size_delta, name))\n\nif not rows:\n    raise SystemExit("no profile compiled")\nrows.sort(reverse=True)\nprint(rows[0][4])\nPY\n)"\n\nprintf \'%s\\n\' "$BEST" >"$BUILD/best-profile.txt"\n\necho "=== CDVD source/header + codegen matrix ==="\nprintf \'%-28s %7s %10s %10s %11s\\n\' \\\n  "profile" "match" "same-size" "size-delta" "diff-bytes"\n\npython3 - "$BUILD/shape-scores.tsv" "$BEST" <<\'PY\'\nimport sys\nfrom pathlib import Path\n\npath = Path(sys.argv[1])\nbest = sys.argv[2]\nrows = []\nfor line in path.read_text(encoding="utf-8").splitlines():\n    p = line.split("\\t")\n    if len(p) != 5:\n        continue\n    if p[1] == "FAIL":\n        rows.append((10**9, p[0], p))\n        continue\n    rows.append((int(p[4]), p[0], p))\n\nrows.sort(key=lambda x: x[0])\nfor _, name, p in rows:\n    marker = "*" if name == best else " "\n    if p[1] == "FAIL":\n        print(f"{marker} {name:<26} COMPILE_FAIL")\n    else:\n        print(\n            f"{marker} {name:<26} {p[1]:>4}/8 "\n            f"{p[2]:>8}/8 {p[3]:>10} {p[4]:>11}"\n        )\nPY\n\necho\necho "=== best profile: $BEST ==="\npython3 tools/score_cdvd_candidate.py \\\n  --target "$RAW" \\\n  --base-address 0x0019be70 \\\n  --object "$BUILD/shape-${BEST}.o" \\\n  --manifest "$MANIFEST"\n\nOBJDUMP="$(dirname "$EE_CC")/ee-objdump"\nif [[ -x "$OBJDUMP" ]]; then\n    "$OBJDUMP" -dr "$BUILD/shape-${BEST}.o" >"$BUILD/best-objdump.txt" 2>/dev/null || true\nfi\n\n# Keep the canonical comparator report for the best candidate.\npython3 tools/compare_elf_functions.py \\\n  --target "$RAW" \\\n  --base-address 0x0019be70 \\\n  --object "$BUILD/shape-${BEST}.o" \\\n  --manifest "$MANIFEST" \\\n  --report analysis/matching/cdvd-rpc-listing-report.md >/dev/null\n\nif python3 tools/score_cdvd_candidate.py \\\n  --target "$RAW" \\\n  --base-address 0x0019be70 \\\n  --object "$BUILD/shape-${BEST}.o" \\\n  --manifest "$MANIFEST" \\\n  --label best --tsv | grep -q $\'^best\\t8\\t\'; then\n    echo\n    echo "=== strict gate ==="\n    python3 tools/compare_elf_functions.py \\\n      --target "$RAW" \\\n      --base-address 0x0019be70 \\\n      --object "$BUILD/shape-${BEST}.o" \\\n      --manifest "$MANIFEST" \\\n      --report analysis/matching/cdvd-rpc-listing-report.md \\\n      --require-all-matching\n    echo "CDVD RPC strict listing gate: OK"\nfi\n\necho\necho "Best profile:    build/matching/cdvd_rpc/best-profile.txt"\necho "Best disassembly: build/matching/cdvd_rpc/best-objdump.txt"\n', encoding="utf-8")
Path("tools/test_progress45_cdvd_exact_shape.py").write_text('from pathlib import Path\nimport unittest\n\nROOT = Path(__file__).resolve().parents[1]\n\n\nclass Progress45CdvdExactShapeTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        cls.candidate = (ROOT / "matching/candidates/cdvd_rpc.c").read_text(\n            encoding="utf-8"\n        )\n        cls.compat = (\n            ROOT / "matching/ee_abi_compat/cdvd_legacy_compat.h"\n        ).read_text(encoding="utf-8")\n        cls.runner = (ROOT / "tools/run-cdvd-frontier.sh").read_text(\n            encoding="utf-8"\n        )\n\n    def test_exact_historical_global_names_and_order(self):\n        self.assertLess(\n            self.candidate.index("static unsigned sbuff[0x1300]"),\n            self.candidate.index("static SifRpcClientData_t cd0"),\n        )\n        self.assertLess(\n            self.candidate.index("static SifRpcClientData_t cd0"),\n            self.candidate.index("int cdvd_inited = 0"),\n        )\n\n    def test_exact_client_header_shape(self):\n        self.assertIn("struct t_SifRpcHeader hdr;", self.compat)\n        self.assertIn("void *end_param;", self.compat)\n        self.assertIn("struct t_SifRpcServerData *server;", self.compat)\n\n    def test_getsize_revision_is_present(self):\n        self.assertIn("#define CDVD_GETSIZE    0x08", self.compat)\n        self.assertIn("unsigned int CDVD_GetSize()", self.candidate)\n\n    def test_matrix_scores_actual_differing_bytes(self):\n        self.assertIn("tools/score_cdvd_candidate.py", self.runner)\n        self.assertIn("o2-no-strict", self.runner)\n        self.assertIn("o2-no-sched1", self.runner)\n        self.assertIn("o2-no-delayed", self.runner)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', encoding="utf-8")
Path("docs/PROGRESS45.md").write_text('# Progress 45 — Exact historical libcdvd source/header fingerprint\n\nProgress 44 showed that O3 is not the missing key.  The best O2+builtins and O3\nprofiles both produced zero exact matches and the same total size delta.\n\nThis progress removes another approximation from the experiment.\n\nThe previous candidate used a padded stand-in type whose only purpose was to\nplace `SifRpcClientData_t.server` at +0x24.  A surviving historical SIF RPC\nheader confirms the complete client layout and the same +0x24 server offset.\nThe candidate now uses that historical field structure, exact global names and\ndeclaration order, and the original function names/source expression shapes.\n\nThe source candidate is also separated from the recovered project source:\n\n- `matching/candidates/cdvd_rpc.c`\n- `matching/ee_abi_compat/cdvd_legacy_compat.h`\n\nThe manifest points at the exact historical symbols.\n\nThe frontier runner now ranks candidates by relocation-normalized differing\nbytes, not only by function size.  This makes compiler fingerprint experiments\nmeaningful even while the exact-match count remains 0/8.\n\nIt tests:\n\n- strict/default/no strict-aliasing;\n- first and second instruction schedulers independently;\n- delayed-branch scheduling;\n- several individual O2 passes;\n- O1/O3 controls;\n- the surviving SNESticle freestanding profile.\n\nNo profile is promoted merely for winning the matrix.  Only the strict byte\ngate can close the corridor.\n', encoding="utf-8")
PY

chmod +x tools/score_cdvd_candidate.py tools/run-cdvd-frontier.sh

echo "Progress 45 applied."
echo "Run only:"
echo "  ./tools/run-cdvd-frontier.sh"
